package quebec.culture.donnees;
import android.app.*;import android.os.*;import android.widget.*;
public class PrivacyActivity extends Activity{
 @Override public void onCreate(Bundle b){super.onCreate(b);Ui.bars(this);LinearLayout r=Ui.root(this);r.addView(Ui.text(this,"Confidentialité et données",28,true));r.addView(Ui.text(this,"Version de la politique : 14 septembre 2026",12,false));LinearLayout p=Ui.panel(this);p.addView(Ui.text(this,"Données traitées",20,true));p.addView(Ui.text(this,"Les catalogues CSV/XLSX que vous importez, les cartographies de champs, les validations humaines, les notes de projet, le budget et les pièces de préparation sont enregistrés localement dans l’espace privé de l’application sur votre appareil.",14,false));r.addView(p);LinearLayout net=Ui.panel(this);net.addView(Ui.text(this,"Accès Internet",20,true));net.addView(Ui.text(this,"L’accès Internet sert à consulter des données culturelles publiques et des pages officielles, ainsi qu’à charger les tuiles de la carte OpenStreetMap. L’application n’envoie pas automatiquement vos catalogues personnels vers un serveur.",14,false));r.addView(net);LinearLayout perms=Ui.panel(this);perms.addView(Ui.text(this,"Permissions et suivi",20,true));perms.addView(Ui.text(this,"Cette version ne demande pas l’accès à la localisation, aux contacts, au microphone ni à la caméra. Elle n’intègre pas de publicité, de compte utilisateur ni de suivi analytique interne.",14,false));r.addView(perms);LinearLayout exp=Ui.panel(this);exp.addView(Ui.text(this,"Export et partage",20,true));exp.addView(Ui.text(this,"Les exports PDF, ZIP ou CSV ne quittent l’appareil que lorsque vous choisissez explicitement un emplacement ou une application de partage avec le sélecteur Android.",14,false));r.addView(exp);LinearLayout del=Ui.panel(this);del.addView(Ui.text(this,"Conservation et suppression",20,true));del.addView(Ui.text(this,"Les données locales restent sur l’appareil tant que l’application ou ses données ne sont pas supprimées. Les fichiers que vous exportez sont ensuite gérés par l’emplacement ou l’application que vous avez choisi.",14,false));r.addView(del);LinearLayout scope=Ui.panel(this);scope.addView(Ui.text(this,"Portée",20,true));scope.addView(Ui.text(this,"Culture du Québec est un outil indépendant de préparation et de normalisation. Il ne représente pas le gouvernement du Québec et ne garantit ni conformité, admissibilité ni financement.",14,false));r.addView(scope);setContentView(Ui.wrap(this,r));}
}
